-- Seed content for the website (safe to re-run: skips rows that exist)




select * from (values
  ('Do I need to bring a partner?', 'Nope. We rotate partners in lessons, and the social floor culture is simple: anyone can ask anyone. Most people show up solo.', 0),
  ('I’ve never danced a step. Which lesson do I take?', 'The 7:30 beginner lesson. It’s fifteen minutes and covers everything you need to join the social at 7:45. Arrive around 7:20 so you can settle in.', 10),
  ('What should I wear?', 'Whatever you can move in. Most people come casual. Shoes that pivot (smoother soles) beat grippy running shoes, but any comfortable shoes work for your first night.', 20),
  ('How much does it cost?', '{door} at the door covers both lessons and the whole social. Cash or card. Student pricing is listed above.', 30),
  ('What’s the difference between the two lessons?', 'The 7:00 advanced lesson assumes you know the fundamentals and moves fast. The 7:30 beginner lesson assumes nothing at all. When in doubt, take both: advanced material is great to watch.', 40),
  ('What exactly is modern swing?', 'A smooth, slotted partner dance descended from swing, danced to current music: pop, R&B, blues. It’s improvised rather than choreographed, so every dance is different.', 50),
  ('Can I just come and watch?', 'Absolutely. Grab a seat by the floor; plenty of people watch a week before they dance. Fair warning: someone will probably ask you to dance anyway.', 60),
  ('Do you allow dips and aerials at the social?', 'Dips with care and consent, aerials never on the social floor. Aerials live in workshops, with mats and spotters.', 70),
  ('Do I need to sign a waiver?', 'Yes, once. Everyone signs a short liability waiver on their first night (a parent or guardian signs for dancers under 18). It takes a minute at the door.', 80)
) v(question, answer, sort) where not exists (select 1 from public.site_faqs);

select * from (values
  ('Grant', 'Instructor', '', 0),
  ('Rhythm', 'Instructor', '', 10),
  ('Zack M.', 'Instructor', '', 20)
) v(name, role, bio, sort) where not exists (select 1 from public.site_instructors);
